contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking a candidate new owner and a boolean that decides
    // whether we attempt the call as owner (true) or as non-owner (false).
    // The checker deploys a fresh C whose owner is this test contract.
    function run(address newOwner, bool callAsOwner) public payable {
        require(newOwner != address(0));

        // Read owner before the attempted change
        address ownerBefore = c.owner();

        // We will attempt to call setOwner from this contract (which is the current owner)
        // or from an externally controlled address using a low-level call simulation by
        // invoking via address(c).call with msg.sender preserved — however the checker
        // executes run exactly once and msg.sender for calls to c will always be this contract.
        // To simulate a non-owner call, we use a delegate helper: deployer cannot change msg.sender,
        // so instead we detect callAsOwner and call setOwner directly when callAsOwner==true,
        // otherwise we attempt a call that will revert because onlyOwner requires msg.sender==owner.

        bool reverted;
        if (callAsOwner) {
            // This contract is the owner (constructor of C was called with this contract as msg.sender),
            // so this call should succeed and return true.
            try c.setOwner(newOwner) returns (bool ok) {
                reverted = false;
                // require that the function returned true when not reverted (not in assert section)
                require(ok == true);
            } catch {
                reverted = true;
            }
        } else {
            // Attempt a call that will revert due to onlyOwner: since msg.sender for calls from this test
            // is always this contract (which is owner), we must cause a revert by calling via address(c).call
            // with empty data that triggers fallback (which doesn't exist) so it will revert — but that wouldn't
            // test setOwner. Instead we call setOwner but first change owner to someone else so this contract
            // is no longer owner, then attempt setOwner which should revert.

            // Change owner to an external address (newOwner) using the legitimate owner call.
            bool succeeded;
            try c.setOwner(newOwner) returns (bool ok) {
                succeeded = ok;
            } catch {
                succeeded = false;
            }
            // After this, owner should be newOwner
            address ownerAfterChange = c.owner();
            // Sanity: require that we successfully changed owner so we can test non-owner revert
            require(succeeded && ownerAfterChange == newOwner);

            // Now this contract is NOT the owner. Attempt to setOwner back to ownerBefore and expect revert.
            try c.setOwner(ownerBefore) returns (bool ok2) {
                // If it does not revert, record that
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read owner after the attempted operation
        address ownerAfter = c.owner();

        // General rule: if the call was made by the current owner it succeeds and updates owner to the provided address;
        // if the call was made by a non-owner it reverts and owner remains unchanged.
        // We express this using the callAsOwner parameter (which determines who initiated the decisive setOwner call).
        if (callAsOwner) {
            // when we called as owner the call must not have reverted and ownerAfter equals newOwner
            assert(reverted == false && ownerAfter == newOwner);
        } else {
            // when we called as non-owner the decisive call must have reverted and owner must still be newOwner (we set it earlier)
            // Note: ownerBefore might equal address(this) originally; after we transferred to newOwner above, ownerAfter should remain newOwner
            assert(reverted == true && ownerAfter == newOwner);
        }
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: candidate new owner and a boolean that decides whether the decisive call is made by the owner (true)
    // or by a non-owner (false).
    function run(address newOwner, bool callAsOwner) public payable {
        require(newOwner != address(0));

        // Read owner before any decisive operation
        address ownerBefore = c.owner();

        // We'll perform state changes as separate top-level calls.
        bool firstSucceeded;
        // If we want to simulate making the decisive call as a non-owner, first transfer ownership away
        if (!callAsOwner) {
            // top-level state-changing call: transfer ownership to newOwner (this call is made by this contract which is the initial owner)
            try c.setOwner(newOwner) returns (bool ok) { firstSucceeded = ok; } catch { firstSucceeded = false; }
        }

        // Now perform the decisive attempt to set owner back to some address depending on callAsOwner:
        bool decisiveReverted;
        if (callAsOwner) {
            // this contract is currently owner, attempt to set to newOwner
            try c.setOwner(newOwner) returns (bool ok2) { decisiveReverted = false; } catch { decisiveReverted = true; }
        } else {
            // this contract is NOT the owner (we transferred above), attempt to set owner back to ownerBefore
            try c.setOwner(ownerBefore) returns (bool ok3) { decisiveReverted = false; } catch { decisiveReverted = true; }
        }

        // Read owner after operations
        address ownerAfter = c.owner();

        // Single assert expressing the invariant for all inputs:
        // - If the decisive call was made as owner, it must not have reverted and ownerAfter equals the attempted new owner.
        // - If the decisive call was made as non-owner, it must have reverted and ownerAfter remains unchanged from before the decisive attempt.
        assert(
            (callAsOwner && decisiveReverted == false && ownerAfter == newOwner)
            || (!callAsOwner && decisiveReverted == true && ownerAfter == (firstSucceeded ? newOwner : ownerBefore))
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function
    // params: address newOwner, bool makeFirstCallTransfer
    function run(address newOwner, bool makeFirstCallTransfer) public payable {
        require(newOwner != address(0));

        // Read owner before any decisive operation
        address ownerBefore = c.owner();

        // We'll perform up to two top-level state-changing calls on c, each as its own statement.
        // First call (optional): if makeFirstCallTransfer is true, try to transfer ownership to newOwner.
        bool firstReverted;
        if (makeFirstCallTransfer) {
            try c.setOwner(newOwner) returns (bool ok) { firstReverted = false; } catch { firstReverted = true; }
        } else {
            firstReverted = true; // indicate no transfer happened
        }

        // Second (decisive) call: attempt to set owner to newOwner again. This contract is the deployer of c,
        // so before any successful transfer it is the owner. After a successful first call it is not.
        bool secondReverted;
        try c.setOwner(newOwner) returns (bool ok2) { secondReverted = false; } catch { secondReverted = true; }

        // Read owner after operations
        address ownerAfter = c.owner();

        // Assert the general rule for all inputs:
        // - If the caller was the owner at the time of a setOwner call, that call must not revert and must set owner to the given address.
        // - If the caller was not the owner at the time, the call must revert and owner stays unchanged by that call.
        // Expressed for the decisive (second) call: if secondReverted==false then ownerAfter==newOwner; if secondReverted==true then ownerAfter==ownerBefore || ownerAfter==newOwner (covers case where first succeeded).
        assert((secondReverted == false && ownerAfter == newOwner) || (secondReverted == true && (ownerAfter == ownerBefore || ownerAfter == newOwner)));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function
    // Params: address candidate - the address to try to set as owner
    function run(address candidate) public payable {
        require(candidate != address(0));

        // Read owner before any state-changing calls
        address ownerBefore = c.owner();

        // Attempt to call setOwner once as this contract (which is the deployer of c and thus the initial owner).
        bool firstReverted;
        try c.setOwner(candidate) returns (bool ok) { firstReverted = false; } catch { firstReverted = true; }

        // Read owner after the first attempt
        address ownerAfterFirst = c.owner();

        // Now attempt a second call to setOwner(candidate) again (to observe behavior when caller may or may not be owner anymore).
        bool secondReverted;
        try c.setOwner(candidate) returns (bool ok2) { secondReverted = false; } catch { secondReverted = true; }

        // Read owner after the second attempt
        address ownerAfterSecond = c.owner();

        // General rule asserted for all inputs and outcomes:
        // - For the first call: if this contract was ownerBefore, the call must not revert and ownerAfterFirst == candidate;
        //   otherwise (if somehow not ownerBefore) it must revert and ownerAfterFirst == ownerBefore.
        // - For the second call: the same rule applies relative to who was owner immediately before that second call (ownerAfterFirst).
        assert(
            // First call correctness
            ((ownerBefore == address(this) && firstReverted == false && ownerAfterFirst == candidate) ||
             (ownerBefore != address(this) && firstReverted == true && ownerAfterFirst == ownerBefore))
            &&
            // Second call correctness (caller is still this contract, but ownership before second call is ownerAfterFirst)
            ((ownerAfterFirst == address(this) && secondReverted == false && ownerAfterSecond == candidate) ||
             (ownerAfterFirst != address(this) && secondReverted == true && ownerAfterSecond == ownerAfterFirst))
        );
    }

    receive() external payable { }
}
